SELECT quotation_entry.QEID, quotation_entry.quot_date, quotation_entry.customer_id, quotation_entry.sale_type, quotation_entry.tax_type, quotation_entry.total_bill, quotation_entry.total_tax, quotation_entry.final_bill, quotation_entry.total_qty, quotation_entry.total_bill_sft, quotation_entry.outputsgst, quotation_entry.outputcgst, quotation_entry.outputigst, items.item_name, quotation_detail.qty, items.unit, ledger.lgID, ledger.contactnumber, ledger.contactaddress, ledger.city, ledger.state, ledger.GSTNo, quotation_detail.mat_sale_price, quotation_detail.amount, quotation_detail.tax_amount, quotation_detail.total_amount, quotation_detail.total_sft, quotation_entry.labour, quotation_entry.discount, quotation_entry.transport, quotation_entry.driver_number
FROM (ledger INNER JOIN quotation_entry ON ledger.lgID = quotation_entry.customer_id) INNER JOIN (items INNER JOIN quotation_detail ON items.item_id = quotation_detail.item_id) ON quotation_entry.QEID = quotation_detail.QEID;

